package za.ac.cput.hospital.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import za.ac.cput.hospital.config.Database;import za.ac.cput.hospital.model.User;import java.io.IOException;import java.sql.*;
@WebServlet("/symptoms") public class SymptomServlet extends HttpServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/views/symptoms.jsp").forward(q,s);}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{String x=q.getParameter("symptoms").toLowerCase();String severity=q.getParameter("severity");String result=x.matches(".*(chest pain|difficulty breathing|unconscious).*?")?"Seek emergency care immediately.":x.matches(".*(fever|cough|sore throat).*?")?"Consider a General Medicine appointment.":"Monitor your symptoms and book a routine consultation if they persist.";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO symptom_checks(patient_id,symptoms,severity,recommendation) VALUES(?,?,?,?)")){p.setInt(1,((User)q.getSession().getAttribute("user")).id());p.setString(2,x);p.setString(3,severity);p.setString(4,result);p.executeUpdate();q.setAttribute("recommendation",result);doGet(q,s);}catch(Exception e){throw new ServletException(e);}}
}
